import { toggleNotifications } from './actions'
import { getNotificationsEnabled } from './lib/preferences'

export default function Home() {
  const enabled = getNotificationsEnabled()

  return (
    <main>
      <h1>Settings</h1>
      <form action={toggleNotifications}>
        <button type="submit">
          Notifications: {enabled ? 'On' : 'Off'}
        </button>
      </form>
    </main>
  )
}

